const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Medina, Saudi Arabia
  const medina = ee.Geometry.Point([39.61, 24.47]);
  const region = medina.buffer(15000); // 15km radius around city center

  // 2. Data acquisition for 1984 (Landsat 5)
  const l5_1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(region)
    .filterDate('1984-06-01', '1984-06-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count1984 = l5_1984.size().getInfo();
  console.log('1984 Images found:', count1984);

  if (count1984 === 0) {
    console.log('No Landsat 5 data for June 1984, trying wider date range');
    const l5_1984_wide = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(region)
      .filterDate('1984-05-01', '1984-07-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    if (l5_1984_wide.size().getInfo() === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Data acquisition for 2018 (Landsat 8)
  const l8_2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2018-07-01', '2018-07-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count2018 = l8_2018.size().getInfo();
  console.log('2018 Images found:', count2018);

  if (count2018 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function for Landsat
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask)
      .multiply(0.0000275).add(-0.2);
  }

  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask)
      .multiply(0.0000275).add(-0.2);
  }

  // 5. Process images and calculate NDBI (Normalized Difference Built-up Index)
  const img1984 = l5_1984.map(maskL5sr).median();
  const img2018 = l8_2018.map(maskL8sr).median();

  // NDBI = (SWIR - NIR) / (SWIR + NIR)
  // Landsat 5: Band 5 (SWIR1=SR_B5), Band 4 (NIR=SR_B4)
  // Landsat 8: Band 6 (SWIR1=SR_B6), Band 5 (NIR=SR_B5)
  const ndbi1984 = img1984.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
  const ndbi2018 = img2018.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');

  // Urban areas typically have NDBI > 0
  const urban1984 = ndbi1984.gt(0);
  const urban2018 = ndbi2018.gt(0);

  // 6. Calculate urban area
  const pixelArea = ee.Image.pixelArea();

  const urbanArea1984 = urban1984.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI');

  const urbanArea2018 = urban2018.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI');

  const validPixels1984 = urban1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI');

  const validPixels2018 = urban2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI');

  const area1984_val = await urbanArea1984.getInfo();
  const area2018_val = await urbanArea2018.getInfo();
  const pixels1984 = await validPixels1984.getInfo();
  const pixels2018 = await validPixels2018.getInfo();

  console.log('Valid pixels 1984:', pixels1984);
  console.log('Valid pixels 2018:', pixels2018);

  if (pixels1984 === 0 || pixels2018 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (area1984_val === null || area2018_val === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  const area1984_km2 = area1984_val / 1e6;
  const area2018_km2 = area2018_val / 1e6;

  console.log('Urban area 1984:', area1984_km2.toFixed(2), 'km²');
  console.log('Urban area 2018:', area2018_km2.toFixed(2), 'km²');
  console.log('Expansion:', (area2018_km2 - area1984_km2).toFixed(2), 'km²');

  if (area2018_km2 > area1984_km2 * 1.1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
